import { Delete02Icon, Tick02Icon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import { Button, cn } from "@procertus-ui/ui";

import { defaultProcertusCategorizationDoc } from "../../categorization-data";
import type { AvailableEntry } from "../../types";
import type { CertificationRequestDraft } from "../../certification-request/types";

const ENTRIES_BY_ID = new Map<string, AvailableEntry>(
  (defaultProcertusCategorizationDoc.meta.availableEntries ?? []).map(
    (entry) => [entry.id, entry],
  ),
);

const FALLBACK_COLUMN_LABEL: Record<string, string> = {
  "product-certification": "Productcertificatie",
};

function columnLabelFor(entryId: string): string {
  return (
    ENTRIES_BY_ID.get(entryId)?.label ??
    FALLBACK_COLUMN_LABEL[entryId] ??
    entryId.toUpperCase()
  );
}

export type StandaloneInquiriesOverviewProps = {
  className?: string;
  /** Aanvragen zonder gekoppeld catalogus-product (bv. innovatie-attest). */
  drafts: readonly CertificationRequestDraft[];
  onRemoveDraft?: (draftId: string) => void;
};

/**
 * Niet-productgebonden aanvragen in dezelfde lay-outmodus als {@link ProductInquiryMatrix}:
 * smal = kaarten; breed (`@xl/inquiry`) = tabel met randen en tick-kolom.
 */
export function StandaloneInquiriesOverview({
  className,
  drafts,
  onRemoveDraft,
}: StandaloneInquiriesOverviewProps) {
  if (drafts.length === 0) return null;

  const showActions = onRemoveDraft != null;

  return (
    <div
      className={cn("@container/inquiry min-w-0 w-full flex flex-col gap-component", className)}
      role="region"
      aria-labelledby="standalone-inquiries-heading"
    >
      <p className="sr-only" id="standalone-inquiries-table-summary">
        Overzicht van aanvragen zonder gekoppeld product uit de catalogus.
        {showActions ? " U kunt een rij verwijderen via de actieknop." : ""}
      </p>

      <div className="flex flex-col gap-micro">
        <h3
          id="standalone-inquiries-heading"
          className="m-0 text-sm font-semibold tracking-tight text-foreground"
        >
          Andere aanvragen
        </h3>
        <p className="m-0 text-xs text-muted-foreground">
          Zonder gekoppeld product uit de productcatalogus.
        </p>
      </div>

      <ul
        className={cn(
          "m-0 flex w-full list-none flex-col gap-component p-0",
          "block @xl/inquiry:hidden",
        )}
        aria-describedby="standalone-inquiries-table-summary"
      >
        {drafts.map((draft) => {
          const typeLabel = columnLabelFor(draft.entryId as string);
          return (
            <li
              key={draft.id}
              className="w-full rounded-lg border border-border/70 bg-card px-component py-component text-card-foreground shadow-sm"
            >
              <div className="flex w-full min-w-0 items-start justify-between gap-component">
                <div className="min-w-0 flex-1">
                  <div className="text-sm font-semibold text-foreground">{draft.label}</div>
                  <p className="mt-component mb-micro text-xs font-medium uppercase tracking-wide text-muted-foreground">
                    Certificaatype
                  </p>
                  <span className="inline-flex max-w-full items-center rounded-md border border-border/80 bg-muted/50 px-2 py-1 text-xs font-medium leading-snug text-foreground">
                    {typeLabel}
                  </span>
                </div>
                {showActions ? (
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="shrink-0 text-muted-foreground hover:text-destructive"
                    aria-label={`Verwijder aanvraag: ${draft.label}`}
                    onClick={() => onRemoveDraft?.(draft.id)}
                  >
                    <HugeiconsIcon icon={Delete02Icon} className="size-4" aria-hidden />
                  </Button>
                ) : null}
              </div>
            </li>
          );
        })}
      </ul>

      <div className={cn("w-full overflow-x-auto", "hidden @xl/inquiry:block")}>
        <table
          className="w-full border-collapse text-sm"
          aria-describedby="standalone-inquiries-table-summary"
        >
          <caption className="sr-only">
            Tabel: overzicht van aanvragen zonder gekoppeld product.
            {showActions ? " Actiekolom verwijdert die aanvraag uit het mandje." : ""}
          </caption>
          <thead>
            <tr className="border-b border-border">
              <th
                scope="col"
                className="py-component pe-component text-start text-xs font-semibold text-muted-foreground"
              >
                Andere aanvragen
              </th>
              <th
                scope="col"
                className="whitespace-nowrap px-component py-component text-center text-xs font-semibold text-muted-foreground"
              >
                Certificaatype
              </th>
              <th
                scope="col"
                className="whitespace-nowrap px-component py-component text-center text-xs font-semibold text-muted-foreground"
              >
                In aanvraag
              </th>
              {showActions ? (
                <th
                  scope="col"
                  className="w-12 px-component py-component text-end text-xs font-semibold text-muted-foreground"
                >
                  <span className="sr-only">Acties</span>
                </th>
              ) : null}
            </tr>
          </thead>
          <tbody>
            {drafts.map((draft) => {
              const typeLabel = columnLabelFor(draft.entryId as string);
              return (
                <tr
                  key={draft.id}
                  className="border-b border-border/60 last:border-b-0"
                >
                  <th
                    scope="row"
                    className="py-component pe-component text-start text-sm font-medium text-foreground"
                  >
                    {draft.label}
                  </th>
                  <td
                    className="px-component py-component text-center text-sm text-muted-foreground"
                    title={typeLabel}
                  >
                    <span className="inline-flex max-w-full items-center justify-center rounded-md border border-border/80 bg-muted/50 px-2 py-1 text-xs font-medium leading-snug text-foreground">
                      {typeLabel}
                    </span>
                  </td>
                  <td className="px-component py-component text-center">
                    <HugeiconsIcon
                      icon={Tick02Icon}
                      aria-label={`${draft.label} opgenomen in het aanvraagpakket`}
                      className="mx-auto size-4 text-primary"
                      strokeWidth={2.25}
                    />
                  </td>
                  {showActions ? (
                    <td className="px-micro py-component text-end align-middle">
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="text-muted-foreground hover:text-destructive"
                        aria-label={`Verwijder ${draft.label} uit het mandje`}
                        onClick={() => onRemoveDraft?.(draft.id)}
                      >
                        <HugeiconsIcon icon={Delete02Icon} className="size-4" aria-hidden />
                      </Button>
                    </td>
                  ) : null}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

